  :Enter power-up mode;
  partition "1) High-voltage shutdown request flag == 2" {
    if (High-voltage shutdown request (charging/discharging) flag == 2?) then (Yes)
      :Switch to state 115;
      partition "1a" {
        if (Flag drops to 0?) then (Yes)
          if (CP duty cycle == 85%?) then (Yes)
            :Switch to state 126;
          elseif (BMS self-check counter == 1?) then (Yes)
            :Switch to state 130;
          endif
        endif
      }
      if (Slow charging becomes inactive?) then (Yes)
        :Shut down;
        end
      endif
      partition "1b" {
        if (Flag drops to 0?) then (Yes)
          if (CP duty cycle == 85%?) then (Yes)
            :Switch to state 126;
          elseif (Battery pre-heating required?) then (Yes)
            :Switch to state 130;
          endif
        endif
      }
      if (Slow charging becomes inactive?) then (Yes)
        :Shut down;
        end
      endif
      partition "1c" {
        if (Flag drops to 0?) then (Yes)
          if (BMS self-check counter == 1?) then (Yes)
            :Switch to state 126;
          elseif (CP duty cycle == 85% && CP amplitude == 3000?) then (Yes)
            :Switch to state 130;
          endif
        endif
      }
      if (Slow charging becomes inactive?) then (Yes)
        :Shut down;
        end
      endif
    endif
  }
  partition "2) Central control command == 2 && not in charging/discharging mode" {
    if (Central control charging/discharging command == 2 && vehicle not in charging/discharging mode?) then (Yes)
      :Switch to state 110;
      if (High-voltage shutdown request flag becomes 2?) then (Yes)
        :Switch to state 115;
      elseif (Flag drops to 0 && CP duty cycle == 88%?) then (Yes)
        :Switch to state 126;
      elseif (Central control command == 1 && charging state == 2?) then (Yes)
        :Switch to state 130;
      endif
      if (Slow charging becomes inactive?) then (Yes)
        :Shut down;
        end
      endif
    endif
  }
else (No)
endif
stop
@enduml

